from __future__ import annotations

from pathlib import Path
from typing import Sequence, Union

from moviepy.editor import AudioFileClip, ImageClip, concatenate_videoclips

from .ffmpeg_utils import run_ffmpeg

PathLike = Union[str, Path]


def _letterbox_image_clip(image_clip: ImageClip, width: int, height: int) -> ImageClip:
    """Mirror FFmpeg letterboxing when MoviePy performs the work."""

    aspect_target = width / height
    aspect_src = image_clip.w / image_clip.h
    if aspect_src > aspect_target:
        resized = image_clip.resize(width=width)
    else:
        resized = image_clip.resize(height=height)
    return resized.on_color(size=(width, height), color=(0, 0, 0), pos=("center", "center"))


def still_with_audio(
    image_path: PathLike,
    audio_path: PathLike,
    output_path: PathLike,
    *,
    fps: int = 30,
    bitrate: str = "4M",
    audio_bitrate: str = "192k",
    width: int | None = None,
    height: int | None = None,
    copy_audio: bool = True,
) -> None:
    """Attach audio to a still image using FFmpeg fallback and MoviePy backup."""

    image = Path(image_path)
    audio = Path(audio_path)
    output = Path(output_path)

    if not image.exists():
        raise FileNotFoundError(f"Image not found: {image}")
    if not audio.exists():
        raise FileNotFoundError(f"Audio not found: {audio}")

    try:
        filters = []
        if width and height:
            filters.append(
                f"scale={width}:{height}:force_original_aspect_ratio=decrease,pad={width}:{height}:(ow-iw)/2:(oh-ih)/2"
            )
        args = [
            "-hide_banner",
            "-loglevel",
            "error",
            "-y",
            "-loop",
            "1",
            "-framerate",
            str(fps),
            "-i",
            str(image),
            "-i",
            str(audio),
            "-c:v",
            "libx264",
            "-tune",
            "stillimage",
            "-pix_fmt",
            "yuv420p",
            "-r",
            str(fps),
            "-shortest",
            "-movflags",
            "+faststart",
        ]
        if filters:
            args.extend(["-vf", filters[0]])
        if copy_audio:
            args.extend(["-c:a", "copy"])
        else:
            args.extend(["-c:a", "aac", "-b:a", audio_bitrate])
        args.extend(["-b:v", bitrate, str(output)])
        run_ffmpeg(args)
        return
    except Exception:
        pass

    with AudioFileClip(str(audio)) as audio_clip:
        image_clip = ImageClip(str(image)).set_duration(audio_clip.duration)
        video_clip = None
        try:
            if width and height:
                image_clip = _letterbox_image_clip(image_clip, width, height)
            video_clip = image_clip.set_audio(audio_clip).set_fps(fps)
            video_clip.write_videofile(
                str(output),
                codec="libx264",
                audio_codec="aac",
                fps=fps,
                bitrate=bitrate,
                audio_bitrate=audio_bitrate,
            )
        finally:
            if video_clip:
                video_clip.close()
            image_clip.close()


def slideshow_with_audio(
    photo_paths: Sequence[PathLike],
    audio_path: PathLike,
    output_path: PathLike,
    *,
    fps: int = 30,
    bitrate: str = "4M",
    audio_bitrate: str = "192k",
) -> None:
    """Display each photo for an equal slice of the audio length."""

    if not photo_paths:
        raise ValueError("photo_paths must contain at least one entry")

    audio_file = Path(audio_path)
    if not audio_file.exists():
        raise FileNotFoundError(f"Audio not found: {audio_file}")

    resolved = [Path(photo) for photo in photo_paths]
    for idx, photo in enumerate(resolved, start=1):
        if not photo.exists():
            raise FileNotFoundError(f"Photo {idx} not found: {photo}")

    with AudioFileClip(str(audio_file)) as audio_clip:
        total_duration = audio_clip.duration
        segment = total_duration / len(resolved)
        durations = [segment] * len(resolved)
        durations[-1] = total_duration - segment * (len(resolved) - 1)

        clips: list[ImageClip] = []
        concat = None
        final_clip = None
        try:
            for path, duration in zip(resolved, durations):
                clip = ImageClip(str(path)).set_duration(duration)
                clips.append(clip)
            concat = concatenate_videoclips(clips, method="compose")
            final_clip = concat.set_audio(audio_clip).set_fps(fps)
            final_clip.write_videofile(
                str(output_path),
                codec="libx264",
                audio_codec="aac",
                fps=fps,
                bitrate=bitrate,
                audio_bitrate=audio_bitrate,
            )
        finally:
            if final_clip:
                final_clip.close()
            if concat:
                concat.close()
            for clip in clips:
                clip.close()
